SELECT 'донор · ' || d.path FROM project_donor d WHERE d.project_id = $1 UNION ALL SELECT 'заморозка · ' || t.path FROM project_frozen_tree t WHERE t.project_id = $1 UNION ALL SELECT 'дерево · ' || f.name FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'frozen-tree' UNION ALL SELECT 'датчик «frozen-tree» ' || fact_gap($1, 'frozen-tree') || ': стоит ли донор — не установлено' WHERE NOT fact_fresh($1, 'frozen-tree')
